const crypto = require('crypto');
const accessKey = 'yCrnfHeNp7sKC5h3';
const secretKey = 'Em2sPDj0VaRGvnnY';
const baseUrl = 'https://metersphere.devops.moego.pet';
const projectId = '20a78db9-19aa-11ee-a261-5a66b98c4036';
const workspaceId = '20a7019f-19aa-11ee-a261-5a66b98c4036';

const timestamp = Date.now();
const uuid = crypto.randomUUID();
const comboxKey = `${accessKey}|${uuid}|${timestamp}`;
const k = Buffer.from(secretKey.slice(0, 16), 'utf-8');
const iv = Buffer.from(accessKey.slice(0, 16), 'utf-8');
const cipher = crypto.createCipheriv('aes-128-cbc', k, iv);
let signature = cipher.update(comboxKey, 'utf-8', 'base64');
signature += cipher.final('base64');

const input = $input.first().json;
if (!input.case_id) throw new Error('case_id is required');
if (!input.name) throw new Error('name is required');

const priority = input.priority || 'P2';
const maintainer = input.maintainer || 'jiabowang@moego.pet';
const status = input.status || 'Prepare';


function normalizeArrayField(value, fieldName, fallback) {
  if (value === undefined || value === null || value === '') {
    return JSON.stringify(fallback);
  }

  let parsed = value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return JSON.stringify(fallback);

    if (trimmed.startsWith('[')) {
      try {
        parsed = JSON.parse(trimmed);
      } catch (error) {
        throw new Error(fieldName + ' must be valid JSON: ' + error.message);
      }
    } else {
      const example = fieldName === 'tags'
        ? '["回归","P0"]'
        : '[{"num":1,"desc":"操作步骤","result":"预期结果"}]';
      throw new Error(fieldName + ' must be a JSON array string, for example: ' + example);
    }
  }

  if (!Array.isArray(parsed)) {
    throw new Error(fieldName + ' must be an array');
  }

  if (fieldName === 'tags') {
    parsed = parsed.map((tag) => String(tag).trim()).filter(Boolean);
  } else if (fieldName === 'steps') {
    parsed = parsed.map((step, index) => {
      if (!step || typeof step !== 'object' || Array.isArray(step)) {
        throw new Error('steps[' + index + '] must be an object');
      }
      return {
        ...step,
        id: step.id || crypto.randomUUID().replace(/-/g, '').slice(0, 8),
        num: Number.isFinite(Number(step.num)) ? Number(step.num) : index + 1,
        desc: String(step.desc ?? ''),
        result: String(step.result ?? ''),
      };
    });
  }

  return JSON.stringify(parsed);
}


async function resolveNodePath(nodeId) {
  const response = await helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/track/case/node/list/' + projectId,
    headers: {
      'Content-Type': 'application/json',
      'ACCEPT': 'application/json',
      'accessKey': accessKey,
      'signature': signature,
      'project': projectId,
      'workspace': workspaceId,
    },
    json: true,
  });

  const data = typeof response === 'string' ? JSON.parse(response) : response;
  if (!data.success) throw new Error('Unable to resolve module path: ' + data.message);

  function find(nodes, parents) {
    for (const node of nodes || []) {
      const names = parents.concat(node.name);
      if (node.id === nodeId) return '/' + names.join('/');
      const childPath = find(node.children, names);
      if (childPath) return childPath;
    }
    return '';
  }

  const path = find(data.data, []);
  if (!path) throw new Error('node_id was not found in the MeterSphere module tree: ' + nodeId);
  return path;
}

let targetNodeId = input.node_id;
if (!targetNodeId && input.case_id) {
  const detailResponse = await helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/track/test/case/get/' + input.case_id,
    headers: {
      'Content-Type': 'application/json',
      'ACCEPT': 'application/json',
      'accessKey': accessKey,
      'signature': signature,
      'project': projectId,
      'workspace': workspaceId,
    },
    json: true,
  });
  const detail = typeof detailResponse === 'string' ? JSON.parse(detailResponse) : detailResponse;
  if (!detail.success) throw new Error('Unable to read existing test case: ' + detail.message);
  targetNodeId = detail.data.nodeId;
}
if (!targetNodeId) throw new Error('node_id is required');
const nodePath = await resolveNodePath(targetNodeId);

const body = {
  id: input.case_id,
  name: input.name,
  num: '',
  nodePath,
  maintainer,
  priority,
  type: 'functional',
  method: '',
  prerequisite: input.prerequisite || '',
  testId: '[]',
  nodeId: targetNodeId,
  steps: normalizeArrayField(input.steps, 'steps', []),
  stepDesc: '',
  stepResult: '',
  selected: [],
  remark: '',
  tags: normalizeArrayField(input.tags, 'tags', []),
  demandId: '',
  demandName: '',
  status,
  reviewStatus: 'Prepare',
  stepDescription: input.step_description || '',
  expectedResult: input.expected_result || '',
  stepModel: input.step_model || 'STEP',
  customNum: '',
  followPeople: '',
  versionId: '3570d801-19aa-11ee-a261-5a66b98c4036',
  follows: [],
  projectId,
  casePublic: false,
  refId: input.case_id,
  latest: true,
  copyCaseId: input.case_id,
  addFields: [],
  editFields: [
    {fieldId: '46065143-9d1d-11eb-b418-0242ac120002', value: JSON.stringify(maintainer)},
    {fieldId: '4619cc23-9d1d-11eb-b418-0242ac120002', value: JSON.stringify(priority)},
    {fieldId: '45f2de57-9d1d-11eb-b418-0242ac120002', value: JSON.stringify(status)},
  ],
  requestFields: [
    {id: '46065143-9d1d-11eb-b418-0242ac120002', name: '责任人', customData: null, type: 'member', value: maintainer},
    {id: '4619cc23-9d1d-11eb-b418-0242ac120002', name: '用例等级', customData: null, type: 'select', value: priority},
    {id: '45f2de57-9d1d-11eb-b418-0242ac120002', name: '用例状态', customData: null, type: 'select', value: status},
  ],
  fields: [
    {id: '45f2de57-9d1d-11eb-b418-0242ac120002', value: status},
    {id: '46065143-9d1d-11eb-b418-0242ac120002', value: maintainer},
    {id: '4619cc23-9d1d-11eb-b418-0242ac120002', value: priority},
  ],
};

const boundary = '------WebKitFormBoundary' + crypto.randomUUID().replace(/-/g, '').slice(0, 16);
const rawBody = '--' + boundary + '\r\nContent-Disposition: form-data; name="request"; filename="blob"\r\nContent-Type: application/json\r\n\r\n' + JSON.stringify(body) + '\r\n--' + boundary + '--\r\n';

const response = await helpers.httpRequest({
  method: 'POST',
  url: `${baseUrl}/track/test/case/edit`,
  headers: {
    'Content-Type': `multipart/form-data; boundary=${boundary}`,
    'ACCEPT': 'application/json',
    'accessKey': accessKey,
    'signature': signature,
    'project': projectId,
    'workspace': workspaceId,
  },
  body: rawBody,
  json: false,
});

const data = typeof response === 'string' ? JSON.parse(response) : response;
if (!data.success) throw new Error(`MeterSphere error: ${data.message}`);
const c = data.data;
return [{ json: { id: c.id, num: c.num, name: c.name, project_id: c.projectId, node_id: c.nodeId, priority: c.priority, status: c.status, maintainer: c.maintainer, update_time: c.updateTime ? new Date(c.updateTime).toISOString() : null, message: 'Test case updated successfully' } }];
